#!/usr/bin/env python3
"""Pocket Club · tests des écrans dans un navigateur sans écran (Playwright), avec le faux client tests/faux_supabase.js.
Usage : python3 tests/ecrans.py [dossier_captures]   (lance un petit serveur local sur le dépôt)
Vérifie qu'aucune erreur JavaScript ne survient sur les écrans principaux et que les parcours clés fonctionnent."""
import http.server, os, sys, threading, functools
from playwright.sync_api import sync_playwright

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT = sys.argv[1] if len(sys.argv) > 1 else None
FAKE = open(os.path.join(ROOT, 'tests', 'faux_supabase.js')).read()
http.server.SimpleHTTPRequestHandler.log_message = lambda *a: None
srv = http.server.ThreadingHTTPServer(('127.0.0.1', 8765), functools.partial(http.server.SimpleHTTPRequestHandler, directory=ROOT))
threading.Thread(target=srv.serve_forever, daemon=True).start()
results, errors = [], []

def check(name, cond):
    results.append((name, bool(cond)))

with sync_playwright() as p:
    b = p.chromium.launch()
    ctx = b.new_context(viewport={'width': 390, 'height': 844}, locale='fr-FR')
    ctx.route('https://cdn.jsdelivr.net/npm/@supabase/**', lambda r: r.fulfill(status=200, content_type='application/javascript', body=FAKE))
    ctx.route('https://fonts.googleapis.com/**', lambda r: r.fulfill(status=200, content_type='text/css', body=''))
    ctx.route('https://challenges.cloudflare.com/**', lambda r: r.fulfill(status=200, content_type='application/javascript', body="window.turnstile={render:function(e,o){setTimeout(function(){o.callback('jeton-test')},0);return 1},reset:function(){}};"))
    ctx.route('https://fonts.gstatic.com/**', lambda r: r.abort())
    pg = ctx.new_page()
    pg.on('pageerror', lambda e: errors.append(str(e)))
    pg.on('console', lambda m: errors.append(m.text) if m.type == 'error' else None)
    pg.add_init_script("navigator.serviceWorker && (navigator.serviceWorker.register = () => Promise.resolve())")
    pg.goto('http://127.0.0.1:8765/index.html')
    try: pg.wait_for_selector('.tb', timeout=8000)
    except Exception: print('ERREURS PAGE:', errors); raise
    shot = lambda n: OUT and pg.screenshot(path=os.path.join(OUT, n + '.png'), full_page=True)
    txt = lambda: pg.inner_text('#app')
    has = lambda t: t.lower() in txt().lower()
    # 5.1.0 (n° 191) : ouvrir directement l'onglet d'une fonction (la page « Gestion du club » n'existe plus)
    fsp = lambda casq, tab: (pg.evaluate("(async()=>{const {S,render}=await import('/js/core.js'); S.ftabs=S.ftabs||{}; S.ftabs['%s']='%s'; S.casq='%s'; S.view={type:'espace'}; S.stack=[]; render();})()" % (casq, tab, casq)), pg.wait_for_timeout(300))
    def act(sel):
        try: pg.click(sel, timeout=4000)
        except Exception: OUT and pg.screenshot(path=os.path.join(OUT, 'erreur.png'), full_page=True); results.append(('clic impossible : ' + sel + ' (écran : ' + pg.inner_text('#app')[:80].replace(chr(10), ' ') + ')', False)); return
        pg.wait_for_timeout(250)

    # 5.5.0 : l'encart « Pour bien démarrer » (testé à part, plus bas) est masqué sur cette page : les cartes d'avant restent testées
    pg.evaluate("(async()=>{const {S,render}=await import('/js/core.js'); const u=S.session.user; u.user_metadata={...(u.user_metadata||{}), onboarding:{hidden:true}}; render();})()"); pg.wait_for_timeout(150)
    check('accueil : salutation et rendez-vous à répondre', has('Salut Gaël') and has('À répondre'))
    check('accueil : demande à valider visible', has('1 demande à valider'))
    check('5.2.1 : seuls les rendez-vous proches ou le prochain de l’équipe comptent (pas la série dans 16 jours, ni les séances libres à 22 jours et plus)', has('4 réponses à donner') and has('1 sur 4'))
    shot('01-accueil')
    act('[data-act=tab][data-i="1"]')
    check('n° 52 : séance lointaine sans « À répondre » dans l’agenda', pg.evaluate("!document.querySelector('[data-act=event][data-id=e6b] .pill.wait') && !!document.querySelector('[data-act=event][data-id=e6] .pill.wait')"))
    check('5.2.1 : trois entraînements libres loin devant, alors que l’équipe a des rendez-vous plus proches : aucun n’est « À répondre »', pg.evaluate("!document.querySelector('[data-act=event][data-id=e9a] .pill.wait') && !document.querySelector('[data-act=event][data-id=e9b] .pill.wait') && !document.querySelector('[data-act=event][data-id=e9c] .pill.wait')"))

    # n° 57 : scénarios de contrôle sur des séances fictives (série de 9 séances, deux séries, séances sans lien), en avançant l'horloge
    ctl = pg.evaluate("""async () => {
      const { S } = await import('/js/core.js'); const A = await import('/js/agenda.js');
      const saved = S.events, realNow = Date.now, base = realNow(), D = 864e5;
      const mk = (id, d, series, title) => ({ id, series_id: series, type: 'Entraînement', title, team_ids: ['t-x'], created_by: 'u-x', starts_at: new Date(base + d * D).toISOString(), cancelled: false });
      const weekly = (pfx, first, series, title, n = 9) => Array.from({ length: n }, (_, i) => mk(pfx + i, first + 7 * i, series, title));
      const open = (at) => { Date.now = () => base + at * D; try { return S.events.filter((e) => new Date(e.starts_at).getTime() >= Date.now() - 2 * 3600e3 && A.isOpen(e)).map((e) => e.id).join(','); } finally { Date.now = realNow; } };
      const out = {};
      S.events = weekly('a', 8, 'sA', 'Série A');
      out.serie_0 = open(0); out.serie_8 = open(8); out.serie_8h = open(8.2);
      S.events = [...weekly('b', 8, 'sB', 'Mardi'), ...weekly('c', 10, 'sC', 'Jeudi')];
      out.deux_series = open(0);
      S.events = weekly('d', 8, null, 'Sans lien');
      out.sans_lien_0 = open(0); out.sans_lien_8 = open(8);
      S.events = [mk('e0', 8, null, 'Libre'), { ...mk('e1', 15, null, 'Libre'), created_by: 'u-y' }, { ...mk('e2', 22, null, 'Libre'), type: 'Match' }];
      out.pas_un_groupe = open(0);
      S.events = [{ ...mk('m0', 3, null, 'Match'), type: 'Match' }, ...weekly('f', 10, 'sF', 'Samedi', 3)];
      out.match_puis_seance = open(0); out.match_passe = open(4);
      S.events = [{ ...mk('k0', 30, null, 'AG'), type: 'Réunion', team_ids: [] }, { ...mk('k1', 60, null, 'Fête'), type: 'Fête', team_ids: [] }];
      out.club_jusqu_a_reponse = open(0);
      S.events = saved;
      return out;
    }""")
    check('n° 57 : série de 9 séances → une seule séance à répondre', ctl['serie_0'] == 'a0')
    check('n° 57 : 8 jours plus tard → la deuxième séance apparaît', ctl['serie_8'] == 'a0,a1' and ctl['serie_8h'] == 'a1')
    check('5.2.1 : mardi et jeudi de la même équipe → seule la prochaine séance, la suivante 7 jours avant', ctl['deux_series'] == 'b0')
    check('n° 57 : séances identiques sans lien de série → même résultat qu’une série', ctl['sans_lien_0'] == 'd0' and ctl['sans_lien_8'] == 'd0,d1')
    check('5.2.1 : même équipe, créateur différent ou match → un seul rendez-vous d’équipe à répondre (le prochain)', ctl['pas_un_groupe'] == 'e0')
    check('5.2.1 : prochain match dans 3 jours → l’entraînement dans 10 jours n’est pas en encart', ctl['match_puis_seance'] == 'm0' and ctl['match_passe'] == 'f0')
    check('5.2.1 : rendez-vous du club → en encart jusqu’à la réponse, sans attendre 7 jours', ctl['club_jusqu_a_reponse'] == 'k0,k1')
    act('[data-act=event][data-id=e6b]')
    check('n° 52 : on peut répondre en avance, date d’entrée annoncée', has('Tu peux répondre dès maintenant') and pg.locator('[data-act=rsvp][data-p=p-lily]').count() >= 1)
    act('[data-act=back]')
    act('[data-act=event][data-id=e1b]')
    check('n° 52 : coach, séance pas encore ouverte : pas de « sans réponse »', has('Réponses demandées à partir du') and not has('sans réponse'))
    act('[data-act=back]')
    check('agenda : réunion de bureau passée rangée dans « Passés »', has('Passés'))
    check('agenda : rendez-vous U9 et U11 affiché', has('Photo U9 et U11'))
    shot('02-agenda')
    act('[data-act=event][data-id=e1]')
    check('rendez-vous : coach encadrant ne répond pas pour lui', has('Tu encadres'))
    check('rendez-vous en série : deux choix de suppression', has('Supprimer cette séance') and has('Supprimer toutes les séances à venir'))
    act('[data-act=evdel][data-m=series]')
    check('suppression de série : confirmation avec le nombre de séances', has('Confirmer : 2 séances supprimées'))
    shot('03-rendez-vous')
    act('[data-act=evdel][data-m=series]')
    check('suppression de série : les 2 séances à venir ont disparu', pg.evaluate("window.__FAKE.events.filter(e => e.series_id === 's1').length") == 0)
    act('[data-act=tab][data-i="1"]')
    act('[data-act=event][data-id=e2]')
    act('[data-act=rsvp][data-p=p-lily][data-v=oui]')
    check('parent : réponse au nom de Lily enregistrée', pg.evaluate("window.__FAKE.event_responses.some(r => r.player_id === 'p-lily' && r.answer === 'oui')"))
    act('[data-act=back]')
    act('[data-act=evnew]')
    act('[data-act=evaud][data-v=team]')
    act('[data-act=evteam][data-id=t-u9]'); act('[data-act=evteam][data-id=t-u11]')
    check('formulaire : deux équipes choisies', has('Équipes (2)'))
    act('[data-act=evaud][data-v=people]')
    pg.check('[data-evpeople=u-s1]'); pg.wait_for_timeout(200)
    check('formulaire : personnes choisies', has('Personnes choisies (1)'))
    shot('04-nouveau-rendez-vous')
    pg.fill('#et', 'Commission buvette'); pg.click('#evf [type=submit]'); pg.wait_for_timeout(400)
    check('création pour des personnes choisies', pg.evaluate("window.__FAKE.events.some(e => e.title === 'Commission buvette' && e.audience === 'people' && e.people[0] === 'u-s1')"))
    # ---------- 3.9.0 · n° 111 titre écrit tout seul, n° 108 case « Match à domicile » ----------
    val = lambda: pg.input_value('#et')
    act('[data-act=evnew]')
    check('n° 111 : nouveau rendez-vous : titre écrit tout seul (« Entraînement - … »)', val().startswith('Entraînement - ') and has('Écrit tout seul'))
    act('[data-act=evaud][data-v=team]'); act('[data-act=evteam][data-id=t-u9]')
    check('n° 111 : entraînement : catégorie et genre de l’équipe, jamais son nom', val().startswith('Entraînement U9 mixte - '))
    pg.check('[data-evrep]'); pg.wait_for_timeout(250)
    check('n° 111 : entraînement répété : « chaque <jour> <heure> »', ' - chaque ' in val())
    act('[data-act=evtype][data-v=Match]')
    check('n° 108 : case « Match à domicile » visible dès qu’on choisit un match', pg.locator('.homebox [data-evhome]').count() == 1 and has('Match à domicile'))
    check('n° 111 : adversaire et date avant le titre', pg.evaluate("(() => { const f = [...document.querySelectorAll('#evf input')].map(i => i.id); return f.indexOf('eo') < f.indexOf('et') && f.indexOf('ed') < f.indexOf('et'); })()"))
    pg.evaluate("(() => { const i = document.querySelector('#evf [name=starts_at]'); i.value = '2026-11-10T14:00'; i.dispatchEvent(new Event('change', { bubbles: true })); })()"); pg.wait_for_timeout(250)
    pg.fill('#eo', 'Palaiseau'); pg.wait_for_timeout(150)
    check('n° 111 : « Match vs Palaiseau - 10/11/26 » rempli tout seul', val() == 'Match vs Palaiseau - 10/11/26')
    shot('04b-titre-automatique')
    pg.fill('#et', 'Finale du dimanche'); pg.wait_for_timeout(150)
    pg.fill('#eo', 'Massy'); pg.wait_for_timeout(150)
    check('n° 111 : titre modifié à la main : gardé, lien pour revenir au titre automatique', val() == 'Finale du dimanche' and pg.locator('[data-act=evtauto]').count() == 1)
    act('[data-act=evtauto]')
    check('n° 111 : retour au titre automatique', val() == 'Match vs Massy - 10/11/26')
    act('[data-act=back]')
    act('[data-act=event][data-id=e2]'); act('[data-act=evedit][data-id=e2]')
    check('n° 111 : rendez-vous existant : son titre est gardé', val() == 'Match contre Val Vert')
    act('[data-act=back]'); act('[data-act=back]')
    # n° 58 : l'heure choisie est celle qui est enregistrée (aucun décalage), et un titre qui cite une autre heure déclenche un avertissement
    msgs = []
    pg.once('dialog', lambda dlg: (msgs.append(dlg.message), dlg.dismiss()))
    act('[data-act=evnew]')
    act('[data-act=evaud][data-v=club]')
    pg.fill('#et', 'Samedi exceptionnellement à 12h')
    pg.evaluate("(() => { const i = document.querySelector('#evf [name=starts_at]'); i.value = '2026-11-07T20:00'; i.dispatchEvent(new Event('input', { bubbles: true })); })()")
    pg.click('#evf [type=submit]'); pg.wait_for_timeout(400)
    check('n° 58 : titre « à 12h » avec heure 20 h : avertissement, rien d’enregistré', len(msgs) == 1 and 'parle de 12 h' in msgs[0] and '20 h 00' in msgs[0] and not pg.evaluate("window.__FAKE.events.some(e => e.title === 'Samedi exceptionnellement à 12h')"))
    pg.evaluate("(() => { const i = document.querySelector('#evf [name=starts_at]'); i.value = '2026-11-07T12:00'; i.dispatchEvent(new Event('input', { bubbles: true })); })()")
    pg.click('#evf [type=submit]'); pg.wait_for_timeout(400)
    check('n° 58 : titre et heure cohérents : enregistré, 12 h à l’affichage comme à la saisie', pg.evaluate("(() => { const e = window.__FAKE.events.find(x => x.title === 'Samedi exceptionnellement à 12h'); const d = e && new Date(e.starts_at); return !!d && d.getHours() === 12 && d.getMinutes() === 0 && d.getDate() === 7; })()"))
    act('[data-act=selmode]')
    pg.check('[data-evsel=e4]'); pg.wait_for_timeout(200)
    check('sélection multiple : barre de suppression', has('1 rendez-vous sélectionné'))
    act('[data-act=seldel]'); act('[data-act=seldel]')
    check('sélection multiple : rendez-vous supprimé', pg.evaluate("!window.__FAKE.events.some(e => e.id === 'e4')"))
    act('[data-act=tab][data-i="2"]'); act('[data-act=group][data-id=g1]')
    check('groupe : message et sondage', has('covoiturage') and has('Présent au plateau'))
    shot('05-groupe')
    act('[data-act=polldel]'); act('[data-act=polldel]')
    check('sondage à la corbeille, restaurable', has('supprimé par') and has('Restaurer'))
    act('[data-act=tab][data-i="3"]'); act('[data-act=teamsel][data-id=t-u9]')
    check('équipe : rappel des dates de naissance', has('date de naissance manque'))
    check('n° 93 · coach : une seule liste « Joueurs », chiffres de l’effectif en une ligne, plus de bloc « Effectif »', has('Joueurs') and has('licencié') and has('préinscrit') and has('cotisations') and pg.locator('.sec h2:text-is("Effectif")').count() == 0 and pg.locator('.sec h2:text-is("Coachs")').count() == 0)
    check('n° 95 · plus de bouton « Ajouter des joueurs » dans l’onglet Équipe', pg.locator('#app [data-act=import]').count() == 0)
    shot('06-equipe')
    act('[data-act=player][data-id=p-tom]')
    check('fiche : contact importé du parent', has('Contact du parent (importé)'))
    shot('07-fiche')
    act('[data-act=pdel]'); act('[data-act=pdel]')
    check('fiche mise à la corbeille', pg.evaluate("!!window.__FAKE.players.find(p => p.id === 'p-tom').deleted_at"))
    act('[data-act=tab][data-i="4"]')
    check('n° 101 · onglet Club : code, plus de carte « Gestion du club » (la gestion est dans l’espace)', has('AB3CD4EF') and pg.locator('#app main [data-act=gestion]').count() == 0)
    act('[data-act=espace]'); act('[data-act=casq][data-v="f:Trésorier"]'); act('[data-act=ftab][data-v=cotis]')
    check('n° 191 · plus de bouton « Gestion du club » en bas de l’espace d’une fonction', pg.locator('[data-act=gestion]').count() == 0 and not has('Gestion du club'))
    y0 = pg.evaluate("(() => { window.scrollTo(0, 300); return window.scrollY; })()")
    pg.evaluate("document.querySelector('main [data-act=player]').click()"); pg.wait_for_timeout(300)
    check('n° 101 · une page ouverte depuis un espace défilé s’ouvre en haut', y0 > 100 and pg.evaluate("window.scrollY") == 0)
    pg.evaluate("document.querySelector('[data-act=back]').click()"); pg.wait_for_timeout(300)
