    act('[data-act=ftab][data-v=rubs]')
    check('n° 194 · onglet « Accès en plus », plus de « Rubriques » à l’écran', pg.locator('.ttabs button:text-is("Accès en plus")').count() == 1 and not has('Rubriques'))
    act('[data-act=rub][data-id=secretariat]')
    check('n° 191 · demandes à valider dans le Secrétariat ; rangée des rôles dans l’en-tête', has('Zoé Martin') and pg.locator('.casq [data-act=casq]').count() >= 2)
    check('n° 191 · effectifs par équipe dans le Secrétariat', pg.locator('#effectifs').count() == 1)
    act('[data-act=back]'); act('[data-act=rub][data-id=commun]')
